extends BaseTest
## TEMP-DEBUG: дамп состояния застывшего боя в headless-прогоне BalanceProbe.
const TestWait := preload("res://tests/helpers/wait_helpers.gd")
var _world: Node = null
var _pilot: Node = null

func after_test() -> void:
	if _pilot != null and is_instance_valid(_pilot):
		_pilot.queue_free()
	if _world != null and is_instance_valid(_world):
		_world.queue_free()
		await get_tree().process_frame
	_world = null
	_pilot = null

func _dump_battle() -> void:
	var b: Node = get_tree().root.get_node_or_null("Battle")
	if b == null:
		print("BATTLE: no node")
		return
	if not b.has_method("get_battle_state"):
		print("BATTLE: node без get_battle_state")
		return
	var bs = b.get_battle_state()
	if bs == null:
		print("BATTLE: state == null")
		return
	var atk := 0
	var def := 0
	for u in bs.attacker_units:
		if u.is_alive():
			atk += 1
	for u in bs.defender_units:
		if u.is_alive():
			def += 1
	var au = bs.active_unit
	print("BATTLE: over=", bs.battle_over, " winner=", bs.battle_winner,
